import{_ as a,o as t,c as r,am as n}from"./chunks/framework.DaYRybuL.js";const p=JSON.parse('{"title":"Glossaire","description":"","frontmatter":{"titre":"Glossaire"},"headers":[],"relativePath":"glossaire.md","filePath":"glossaire.md"}'),o={name:"glossaire.md"};function s(i,e,l,u,d,c){return t(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="glossaire" tabindex="-1">Glossaire <a class="header-anchor" href="#glossaire" aria-label="Permalink to &quot;Glossaire&quot;">​</a></h1><h3 id="agent-de-code" tabindex="-1">Agent de code <a class="header-anchor" href="#agent-de-code" aria-label="Permalink to &quot;Agent de code&quot;">​</a></h3><p>Agent qui lit, modifie et exécute du code dans un dépôt (Copilot, Claude Code, Codex, Cursor…).</p><h3 id="boucle-agentique" tabindex="-1">Boucle agentique <a class="header-anchor" href="#boucle-agentique" aria-label="Permalink to &quot;Boucle agentique&quot;">​</a></h3><p>Le cycle demande → le modèle choisit un tool → le harness l&#39;exécute → le résultat entre dans le contexte → on recommence si besoin.</p><h3 id="budget-d-erreur" tabindex="-1">Budget d&#39;erreur <a class="header-anchor" href="#budget-d-erreur" aria-label="Permalink to &quot;Budget d&#39;erreur&quot;">​</a></h3><p>Ce que le SLO autorise à échouer sur sa fenêtre : avec 99,5 % de succès sur 30 jours, 0,5 % des requêtes. Une alerte utile sonne quand ce budget se consomme trop vite, pas à chaque erreur.</p><h3 id="ci-integration-continue" tabindex="-1">CI (intégration continue) <a class="header-anchor" href="#ci-integration-continue" aria-label="Permalink to &quot;CI (intégration continue)&quot;">​</a></h3><p>Les vérifications lancées automatiquement à chaque changement du code (construire, tester) avant qu&#39;il parte en production.</p><h3 id="context-window" tabindex="-1">Context window <a class="header-anchor" href="#context-window" aria-label="Permalink to &quot;Context window&quot;">​</a></h3><p>Tout ce que le modèle « voit » au moment de répondre : consignes, historique, pièces jointes, résultats des tools.</p><h3 id="cronjob" tabindex="-1">CronJob <a class="header-anchor" href="#cronjob" aria-label="Permalink to &quot;CronJob&quot;">​</a></h3><p>Une tâche planifiée de Kubernetes (un batch lancé à heure fixe). Sans <code>spec.timeZone</code>, son horaire s&#39;entend en général en UTC.</p><h3 id="expand-contract" tabindex="-1">Expand / contract <a class="header-anchor" href="#expand-contract" aria-label="Permalink to &quot;Expand / contract&quot;">​</a></h3><p>Changer un schéma de base en deux temps : ajouter le nouveau (table, colonne) et faire cohabiter l&#39;ancien, puis supprimer l&#39;ancien dans une version suivante, une fois la nouvelle stable. Chaque étape garde un retour arrière possible.</p><h3 id="fatigue-d-alerte" tabindex="-1">Fatigue d&#39;alerte <a class="header-anchor" href="#fatigue-d-alerte" aria-label="Permalink to &quot;Fatigue d&#39;alerte&quot;">​</a></h3><p>Quand trop d&#39;alertes ne demandent aucune action, l&#39;astreinte les acquitte par réflexe, et finit par acquitter aussi la vraie.</p><h3 id="harness" tabindex="-1">Harness <a class="header-anchor" href="#harness" aria-label="Permalink to &quot;Harness&quot;">​</a></h3><p>Tout le logiciel autour du modèle : consignes, mémoire, tools, enchaînement des étapes. Deux assistants sur le même modèle diffèrent par leur harness.</p><h3 id="human-in-the-loop" tabindex="-1">Human-in-the-loop <a class="header-anchor" href="#human-in-the-loop" aria-label="Permalink to &quot;Human-in-the-loop&quot;">​</a></h3><p>Un humain qualifié valide la sortie de l&#39;IA <em>avant</em> qu&#39;elle soit utilisée.</p><h3 id="iac-infrastructure-as-code" tabindex="-1">IaC (Infrastructure as Code) <a class="header-anchor" href="#iac-infrastructure-as-code" aria-label="Permalink to &quot;IaC (Infrastructure as Code)&quot;">​</a></h3><p>L&#39;infrastructure décrite dans des fichiers versionnés (Terraform, manifestes Kubernetes) plutôt que configurée à la main : elle se relit, se teste et se revoit comme du code.</p><h3 id="instructions-projet" tabindex="-1">Instructions projet <a class="header-anchor" href="#instructions-projet" aria-label="Permalink to &quot;Instructions projet&quot;">​</a></h3><p>Fichier versionné dans le dépôt, chargé à chaque session : conventions, commandes, pièges (<code>AGENTS.md</code>, <code>CLAUDE.md</code> pour Claude Code). C&#39;est l&#39;équivalent dev des instructions personnalisées.</p><h3 id="mode-a-blanc-dry-run" tabindex="-1">Mode à blanc (dry-run) <a class="header-anchor" href="#mode-a-blanc-dry-run" aria-label="Permalink to &quot;Mode à blanc (dry-run)&quot;">​</a></h3><p>Un script lancé sans effet : il affiche ce qu&#39;il ferait (les fichiers qu&#39;il supprimerait) sans le faire. Par défaut dans un script qui supprime ; l&#39;action demande une option explicite.</p><h3 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h3><p>Les actions autorisées à l&#39;agent (lire, écrire, lancer une commande, accéder au réseau).</p><h3 id="pool-de-connexions" tabindex="-1">Pool de connexions <a class="header-anchor" href="#pool-de-connexions" aria-label="Permalink to &quot;Pool de connexions&quot;">​</a></h3><p>Les connexions à la base qu&#39;un service ouvre d&#39;avance et se partage. Quand toutes sont prises, les requêtes attendent, puis échouent (« pool exhausted »).</p><h3 id="post-mortem-sans-blame" tabindex="-1">Post-mortem sans blâme <a class="header-anchor" href="#post-mortem-sans-blame" aria-label="Permalink to &quot;Post-mortem sans blâme&quot;">​</a></h3><p>Le compte rendu d&#39;un incident qui cherche ce qui, dans le système, l&#39;a rendu possible, et pas qui s&#39;est trompé : des faits datés et sourcés, des causes, peu d&#39;actions suivies.</p><h3 id="retour-arriere-rollback" tabindex="-1">Retour arrière (rollback) <a class="header-anchor" href="#retour-arriere-rollback" aria-label="Permalink to &quot;Retour arrière (rollback)&quot;">​</a></h3><p>Revenir à l&#39;état d&#39;avant un changement. Il se prévoit avant le déploiement : certaines étapes (supprimer une colonne) le rendent impossible.</p><h3 id="rolling-update" tabindex="-1">Rolling update <a class="header-anchor" href="#rolling-update" aria-label="Permalink to &quot;Rolling update&quot;">​</a></h3><p>Le remplacement progressif des pods d&#39;un service : pendant quelques minutes, l&#39;ancienne et la nouvelle version tournent ensemble, sur la même base.</p><h3 id="runbook" tabindex="-1">Runbook <a class="header-anchor" href="#runbook" aria-label="Permalink to &quot;Runbook&quot;">​</a></h3><p>La fiche d&#39;exploitation d&#39;une alerte ou d&#39;un service : le symptôme, ce qu&#39;on vérifie, ce qu&#39;on fait et qui prévenir.</p><h3 id="session" tabindex="-1">Session <a class="header-anchor" href="#session" aria-label="Permalink to &quot;Session&quot;">​</a></h3><p>Une conversation ; elle accumule du contexte, utile ou parasite.</p><h3 id="signal-et-bruit" tabindex="-1">Signal et bruit <a class="header-anchor" href="#signal-et-bruit" aria-label="Permalink to &quot;Signal et bruit&quot;">​</a></h3><p>Le bruit est présent tout le temps, au même rythme, sans conséquence ; le signal apparaît à un moment précis, souvent juste après un événement (un déploiement, un batch).</p><h3 id="sli-slo" tabindex="-1">SLI, SLO <a class="header-anchor" href="#sli-slo" aria-label="Permalink to &quot;SLI, SLO&quot;">​</a></h3><p>Le SLI est ce qu&#39;on mesure du point de vue de l&#39;utilisateur (part des requêtes en succès, durée) ; le SLO est l&#39;objectif fixé sur ce SLI (99,5 % sur 30 jours).</p><h3 id="token" tabindex="-1">Token <a class="header-anchor" href="#token" aria-label="Permalink to &quot;Token&quot;">​</a></h3><p>Morceau de mot traité par le modèle ; c&#39;est aussi l&#39;unité de facturation (≈ ¾ de mot en anglais).</p><h3 id="tools" tabindex="-1">Tools <a class="header-anchor" href="#tools" aria-label="Permalink to &quot;Tools&quot;">​</a></h3><p>Capacités que le modèle peut appeler pendant sa réponse : recherche web, calcul, lecture de fichiers, Jira, Figma… (<em>tool calling</em>).</p><h3 id="utc" tabindex="-1">UTC <a class="header-anchor" href="#utc" aria-label="Permalink to &quot;UTC&quot;">​</a></h3><p>Le temps universel, sans fuseau. En hiver, 07:45 UTC est 08:45 à Paris : un horaire écrit sans fuseau se vérifie.</p>',51)])])}const m=a(o,[["render",s]]);export{p as __pageData,m as default};
